contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _lockTime, uint _am, uint _putAmount) public payable {
        require(address(this).balance >= _putAmount);

        // Initialize so that SetMinSum / SetLogFile cannot interfere later, and set a log target.
        c.Initialized();

        // Fresh test contract is the only sender.
        address sender = address(this);

        // Read pre-state via public getters.
        (uint preUnlockTime, uint preBalance) = c.Acc(sender);

        // Make a deposit using the fallback/Put path.  Value is taken as a parameter.
        (bool putOk, ) = address(c).call{value: _putAmount}(abi.encodeWithSignature("Put(uint256)", _lockTime));

        // Only reason about the collect rule when the Put itself succeeded.
        // If Put reverted we simply avoid drawing a conclusion from a zero-effect setup.
        // We still must reach one assert, so we compare before/after in a neutral way.
        if (!putOk) {
            (uint afterUnlockTime, uint afterBalance) = c.Acc(sender);
            assert(afterBalance == preBalance && afterUnlockTime == preUnlockTime);
            return;
        }

        // Read the state created by Put, then attempt Collect.
        (uint unlockTime, uint balanceBefore) = c.Acc(sender);

        // Only meaningful when there is a positive recorded balance; otherwise the rule is vacuous
        // and we prove a neutral invariant instead of risking an underflow in the formula.
        if (balanceBefore == 0) {
            (uint b0, uint _x0) = c.Acc(sender);
            assert(b0 == balanceBefore && _x0 == unlockTime);
            return;
        }

        // Collect the requested amount; catch revert.
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint finalUnlockTime, uint balanceAfter) = c.Acc(sender);

        if (balanceBefore < _am) {
            // Collect must have reverted (cannot subtract below zero).
            assert(reverted && balanceAfter == balanceBefore && finalUnlockTime == unlockTime);
        } else if (block.timestamp <= unlockTime) {
            // Lock not expired: must revert.
            assert(reverted && balanceAfter == balanceBefore && finalUnlockTime == unlockTime);
        } else if (balanceBefore < c.MinSum()) {
            // Below minimum sum: must revert.
            assert(reverted && balanceAfter == balanceBefore && finalUnlockTime == unlockTime);
        } else {
            // Otherwise it must succeed and record balance decreases by _am.
            assert(!reverted && balanceAfter == balanceBefore - _am && finalUnlockTime == unlockTime);
        }
    }

    receive() external payable {}
}

