        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        assert((collectReverted && balanceAfter == balanceBefore) || (!collectReverted && balanceBefore >= collectAmount && balanceAfter == balanceBefore - collectAmount));
    }

    receive() external payable {}
}
